/**
 * REST contracts of the ranking and match history APIs.
 * Shared by the Axios client, the TanStack Query hooks and the MSW handlers.
 */
import type { EndReason } from '../game/sim/types'

export type { EndReason }

/** The options a match was played with. Rankings only compare matches with equal settings. */
export interface MatchSettings {
  sessionTimeSec: number
  enemySpawnTimeSec: number
  /** Balancing version of the game configuration. */
  configVersion: string
}

/** Body of `POST /api/matches`. `id` is generated by the client and makes the call idempotent. */
export interface MatchSubmission {
  id: string
  playerId: string
  playerName: string
  /** ISO 8601 timestamp of the end of the match. */
  playedAt: string
  score: number
  /** Effective seconds of active play. */
  durationSec: number
  endReason: EndReason
  settings: MatchSettings
}

export interface MatchRecord extends MatchSubmission {
  /** ISO 8601 timestamp of when the server stored the record. */
  registeredAt: string
}

export interface SubmitMatchResponse {
  record: MatchRecord
  /** False when the match was already registered and the existing record was returned. */
  created: boolean
}

export interface RankingEntry {
  rank: number
  matchId: string
  playerId: string
  playerName: string
  score: number
  durationSec: number
  endReason: EndReason
  playedAt: string
}

export interface Paginated<T> {
  items: T[]
  page: number
  pageSize: number
  totalItems: number
  totalPages: number
}

export interface PageParams {
  page: number
  pageSize: number
}

export interface RankingParams extends PageParams {
  sessionTimeSec: number
  enemySpawnTimeSec: number
}

export interface ApiErrorBody {
  message: string
}

export const API_ROUTES = {
  ranking: '/ranking',
  matches: '/matches',
  playerMatches: (playerId: string) => `/players/${encodeURIComponent(playerId)}/matches`,
} as const

/** Identifies a ranking board: matches are only compared when their settings key is equal. */
export function settingsKey(
  settings: Pick<MatchSettings, 'sessionTimeSec' | 'enemySpawnTimeSec'>,
): string {
  return `${settings.sessionTimeSec}s-${settings.enemySpawnTimeSec}s`
}

/**
 * Deterministic ranking order: higher score first; ties go to the match played earlier,
 * then to the lexicographically smaller match id.
 */
export function compareRanking(
  a: Pick<MatchRecord, 'score' | 'playedAt' | 'id'>,
  b: Pick<MatchRecord, 'score' | 'playedAt' | 'id'>,
): number {
  if (a.score !== b.score) return b.score - a.score
  if (a.playedAt !== b.playedAt) return a.playedAt < b.playedAt ? -1 : 1
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0
}

const END_REASONS: readonly string[] = ['time_up', 'player_destroyed']

export function isMatchSubmission(value: unknown): value is MatchSubmission {
  if (typeof value !== 'object' || value === null) return false
  const match = value as Record<string, unknown>
  const settings = match.settings as Record<string, unknown> | null | undefined
  return (
    typeof match.id === 'string' &&
    match.id.length > 0 &&
    typeof match.playerId === 'string' &&
    typeof match.playerName === 'string' &&
    typeof match.playedAt === 'string' &&
    !Number.isNaN(Date.parse(match.playedAt)) &&
    typeof match.score === 'number' &&
    Number.isInteger(match.score) &&
    match.score >= 0 &&
    typeof match.durationSec === 'number' &&
    match.durationSec >= 0 &&
    typeof match.endReason === 'string' &&
    END_REASONS.includes(match.endReason) &&
    typeof settings === 'object' &&
    settings !== null &&
    typeof settings.sessionTimeSec === 'number' &&
    typeof settings.enemySpawnTimeSec === 'number' &&
    typeof settings.configVersion === 'string'
  )
}
